#include "../standalone/original.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc==6&&std::string(argv[1]).rfind("swap",0)==0){auto working=studio::identifyDirectory(argv[2]),returned=studio::identifyDirectory(argv[3]);auto identity=studio::identifyOriginal(argv[4]);studio::handleOriginal(argv[4],identity,"move",argv[5],[](){},[](const char*){},[](uint64_t,uint64_t){});if(std::string(argv[1])=="swap-changed"){std::filesystem::rename(argv[2],std::string(argv[2])+"-saved");std::filesystem::create_directory(argv[2]);}studio::finishSwap(argv[2],working,argv[3],returned,argv[4],argv[5],identity,[&](){if(std::string(argv[1])=="swap-cancel")throw std::runtime_error("Canceled");});return 0;}if(argc==2&&std::string(argv[1])=="consent"){studio::requireDeleteConsent("delete",true,false,false);return 0;}if(argc==2&&std::string(argv[1])=="unverified-consent"){studio::requireDeleteConsent("delete",false,true,false);return 0;}if(argc==2&&std::string(argv[1])=="confirmed"){studio::requireDeleteConsent("delete",false,true,true);return 0;}if(argc!=4)return 2;std::string command=argv[1];auto identity=studio::identifyOriginal(argv[2]);if(command=="changed"){std::ofstream file(argv[2],std::ios::app);file<<"change";file.close();}studio::handleOriginal(argv[2],identity,command=="delete"?"delete":"move",argv[3],[&](){if(command=="cancel")throw std::runtime_error("Canceled");},[](const char* name){std::cout<<name<<"\n";},[](uint64_t,uint64_t){});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
